# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">EXPRESSING PAST HABITS &amp; STATES: USED TO + V1</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">GRAMMAR FORMS OF \'USED TO\'</text>\n  <rect x="35" y="78" width="290" height="40" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="94" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Affirmative (+): Subject + used to + V1</text>\n  <text x="180" y="110" text-anchor="middle" font-size="9.5" fill="#334155">She used to work at a textile factory in her youth.</text>\n  <rect x="35" y="124" width="290" height="40" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="140" text-anchor="middle" font-size="10" font-weight="bold" fill="#dc2626">Negative (-): Subject + didn\'t use to + V1</text>\n  <text x="180" y="156" text-anchor="middle" font-size="9.5" fill="#334155">They didn\'t use to have electricity in that village.</text>\n  <rect x="35" y="170" width="290" height="40" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="186" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Interrogative (?): Did + S + use to + V1?</text>\n  <text x="180" y="202" text-anchor="middle" font-size="9.5" fill="#334155">Did you use to walk to school every morning?</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">DO NOT CONFUSE! (KARIŞTIRMAYIN)</text>\n  <rect x="375" y="80" width="290" height="58" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">1. used to + V1 (Eskiden ... yapardı):</text>\n  <text x="520" y="114" text-anchor="middle" font-size="9.5" fill="#334155">I used to wake up late. (Geçmişte kaldı, bitti.)</text>\n  <rect x="375" y="146" width="290" height="62" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="520" y="164" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">2. be / get used to + V-ing / Noun (Alışkın olmak):</text>\n  <text x="520" y="180" text-anchor="middle" font-size="9.5" fill="#334155">I am used to waking up early now. (Şu an alışkınım.)</text>\n  <text x="520" y="196" text-anchor="middle" font-size="9.5" fill="#334155">He got used to living in cold weather. (Alıştı.)</text>\n</svg>', '<svg viewBox="0 0 700 220" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="220" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">COMPARISON: \'USED TO\' VS. \'WOULD\' IN THE PAST</text>\n  <rect x="20" y="48" width="320" height="152" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">1. ACTION VERBS (Eylem Fiilleri)</text>\n  <rect x="35" y="82" width="290" height="104" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.2"/>\n  <text x="180" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Hem \'used to\' hem \'would\' DOĞRUDUR:</text>\n  <text x="180" y="124" text-anchor="middle" font-size="9.5" fill="#334155">• play, go, visit, help, read, walk, tell...</text>\n  <text x="180" y="146" text-anchor="middle" font-size="9.5" fill="#334155">Every summer, we used to / would go fishing</text>\n  <text x="180" y="162" text-anchor="middle" font-size="9.5" fill="#334155">with my uncle by the lake.</text>\n\n  <rect x="360" y="48" width="320" height="152" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="70" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">2. STATIVE VERBS (Durum Fiilleri)</text>\n  <rect x="375" y="82" width="290" height="104" rx="6" fill="#ffffff" stroke="#f87171" stroke-width="1.2"/>\n  <text x="520" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">\'used to\' DOĞRU — \'would\' YANLIŞTIR!</text>\n  <text x="520" y="124" text-anchor="middle" font-size="9.5" fill="#334155">• be, have (iyelik), live, know, own, love, hate...</text>\n  <text x="520" y="146" text-anchor="middle" font-size="9.5" fill="#15803d">DOĞRU: He used to have a classic car.</text>\n  <text x="520" y="164" text-anchor="middle" font-size="9.5" fill="#dc2626">YANLIŞ: He would have a classic car.</text>\n</svg>', '<svg viewBox="0 0 700 220" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="220" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">THEME 3: HARD TIMES — NARRATIVE TENSES &amp; IDIOMS</text>\n  <rect x="20" y="48" width="330" height="152" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="1.8"/>\n  <text x="185" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#3730a3">NARRATIVE TENSES IN BIOGRAPHIES</text>\n  <text x="185" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• Simple Past (V2): Main events in chronological order.</text>\n  <text x="185" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Past Continuous (was/were V-ing): Background action.</text>\n  <text x="185" y="134" text-anchor="middle" font-size="9.5" fill="#334155">• Past Perfect (had + V3): Earlier past action (before V2).</text>\n  <text x="185" y="154" text-anchor="middle" font-size="9.5" fill="#334155">• Used to / Would + V1: Past habits and living conditions.</text>\n  <text x="185" y="176" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#4338ca">By the time he succeeded, he had failed many times.</text>\n\n  <rect x="365" y="48" width="315" height="152" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="522" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">KEY VOCABULARY &amp; IDIOMS</text>\n  <text x="522" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• Overcome adversity / obstacles: Zorlukları aşmak</text>\n  <text x="522" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Perseverance &amp; Resilience: Azim ve dayanıklılık</text>\n  <text x="522" y="134" text-anchor="middle" font-size="9.5" fill="#334155">• Make ends meet: Kıt kanaat geçinmek</text>\n  <text x="522" y="154" text-anchor="middle" font-size="9.5" fill="#334155">• Hit rock bottom: En dibe vurmak</text>\n  <text x="522" y="174" text-anchor="middle" font-size="9.5" fill="#334155">• Turn over a new leaf: Yeni bir sayfa açmak</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
